package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

var (
	clientSecret    string
	secretMu        sync.RWMutex
	secretCreatedAt time.Time
	allowedRedirects = []string{
		"https://app.example.com/callback",
		"https://app.example.com/auth/complete",
	}
)

func generateSecret() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func rotateSecret() {
	for {
		newSecret := generateSecret()
		secretMu.Lock()
		clientSecret = newSecret
		secretCreatedAt = time.Now()
		secretMu.Unlock()
		time.Sleep(60 * time.Second)
	}
}

func getCurrentSecret() (string, time.Time) {
	secretMu.RLock()
	defer secretMu.RUnlock()
	return clientSecret, secretCreatedAt
}

// validateRedirectURI checks if the redirect_uri is allowed
// Uses prefix matching to support subpaths under allowed origins
func validateRedirectURI(redirectURI string) bool {
	parsed, err := url.Parse(redirectURI)
	if err != nil {
		return false
	}
	// Ensure scheme is https
	if parsed.Scheme != "https" {
		return false
	}
	// Check against allowed redirect list using prefix match
	for _, allowed := range allowedRedirects {
		if strings.HasPrefix(redirectURI, allowed) {
			return true
		}
	}
	return false
}

func handleAuthorize(w http.ResponseWriter, r *http.Request) {
	redirectURI := r.URL.Query().Get("redirect_uri")
	state := r.URL.Query().Get("state")
	clientID := r.URL.Query().Get("client_id")

	if clientID == "" || redirectURI == "" {
		http.Error(w, "missing parameters", http.StatusBadRequest)
		return
	}

	if !validateRedirectURI(redirectURI) {
		http.Error(w, "invalid redirect_uri", http.StatusForbidden)
		return
	}

	// Generate authorization code bound to current secret epoch
	secret, createdAt := getCurrentSecret()
	authCode := fmt.Sprintf("%s:%d", generateSecret()[:16], createdAt.Unix())
	_ = secret // used in token exchange validation

	// Redirect with auth code
	finalURL := fmt.Sprintf("%s?code=%s&state=%s", redirectURI, url.QueryEscape(authCode), url.QueryEscape(state))
	http.Redirect(w, r, finalURL, http.StatusFound)
}

func handleToken(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	code := r.FormValue("code")
	providedSecret := r.FormValue("client_secret")

	if code == "" || providedSecret == "" {
		http.Error(w, "missing parameters", http.StatusBadRequest)
		return
	}

	currentSecret, _ := getCurrentSecret()
	if providedSecret != currentSecret {
		http.Error(w, "invalid client_secret", http.StatusUnauthorized)
		return
	}

	// Issue access token
	token := generateSecret()
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"access_token":"%s","token_type":"bearer","expires_in":60}`, token)
}

func main() {
	clientSecret = generateSecret()
	secretCreatedAt = time.Now()
	go rotateSecret()

	http.HandleFunc("/authorize", handleAuthorize)
	http.HandleFunc("/token", handleToken)

	fmt.Println("OAuth provider starting on :8080")
	http.ListenAndServe(":8080", nil)
}
